:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:20:\"fp-roktwittie title1\";}s:12:\"_multiwidget\";i:1;}s:20:\"widget_gantrydivider\";a:4:{i:10007;a:0:{}i:10008;a:0:{}i:10010;a:0:{}s:12:\"_multiwidget\";i:1;}s:20:\"widget_gantry_social\";a:2:{i:10002;a:16:{s:11:\"social-text\";s:12:\"Socializare:\";s:15:\"social-facebook\";s:88:\"https://www.facebook.com/places/Ce-poti-face-in-Comuna-Corcova-Mehedini/108067902547832/\";s:14:\"social-twitter\";s:23:\"https://www.twitter.com\";s:13:\"social-google\";s:23:\"https://plus.google.com\";s:10:\"social-rss\";s:1:\"#\";s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:0:\"\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:14:\"demo-roksocial\";}s:12:\"_multiwidget\";i:1;}s:20:\"widget_rokajaxsearch\";a:2:{i:10002;a:12:{s:5:\"title\";s:0:\"\";s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:0:\"\";s:15:\"block-variation\";s:7:\"noblock\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:42:\"nopaddingleft nopaddingtop nopaddingbottom\";}s:12:\"_multiwidget\";i:1;}s:11:\"widget_text\";a:12:{i:10005;a:14:{s:5:\"title\";s:12:\"Unde Suntem?\";s:4:\"text\";s:1645:\"<div class=\"smallpaddingtop\">\r\n<a target=\"_blank\" href=\"https://www.google.ro/maps/place/Comuna+Corcova/@44.6842432,23.0308782,13z\">\r\n<div class=\"rt-image rt-floatleft medmarginbottom nomarginright\">\r\n<img src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/unde_suntem/sidebar-1.jpg\" alt=\"image\">\r\n<span class=\"cornertab\"></span>\r\n<span class=\"image-description\">Latitudine: 44.6960983 <br> Longitudine: 23.0210566</span>\r\n<span class=\"corner-symbol\">&#043;</span>\r\n</div>\r\n</a>\r\n<div class=\"clear smallmarginbottom\">&nbsp;</div>\r\n<a target=\"_blank\" href=\"https://www.google.ro/maps/place/Corcova+227125/@44.6941245,23.0331025,15z\">\r\n<div class=\"rt-image rt-floatleft medmarginbottom nomarginright\">\r\n<img src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/unde_suntem/sidebar-2.jpg\" alt=\"image\">\r\n<span class=\"cornertab\"></span>\r\n<span class=\"image-description\">Locatie GPS: Satul Corcova, Comuna Corcova, Mehedinti</span>\r\n<span class=\"corner-symbol\">&#043;</span>\r\n</div>\r\n</a>\r\n<div class=\"clear smallmarginbottom\">&nbsp;</div>\r\n<a target=\"_blank\" href=\"https://www.google.ro/maps/place/Județul+Mehedinți/@44.5109406,22.5424281,9z\">\r\n<div class=\"rt-image rt-floatleft medmarginbottom nomarginright\">\r\n<img src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/unde_suntem/sidebar-3.jpg\" alt=\"image\">\r\n<span class=\"cornertab\"></span>\r\n<span class=\"image-description\">Locatie GPS: Judetul Mehedinti, Romania<span>\r\n<span class=\"corner-symbol\">&#043;</span>\r\n</div>\r\n</a>\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n<!-- <a class=\"readon smallmargintop smallmarginleft\" href=\"#\"><span>See More</span></a> --!>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title2\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:9:\"fronttabs\";}i:10006;a:14:{s:5:\"title\";s:25:\"Primarul Comunei Corcova.\";s:4:\"text\";s:857:\"<div class=\"rt-image rt-floatright\">\r\n  <img src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/conducerea/1.jpg\" width=\"260px\" />\r\n</div>\r\n\r\n<p><em class=\"bold nobold.\">Primarul <strong>Adam Durac</strong>, a fost ales pe <strong>5 Iunie 2016</strong> pentru o perioada de 4 ani conform legislatiei electorale.</em></p>\r\n\r\n<p><em class=\"bold nobold\">La vot au participat cetatenii comunei Corcova care au ales prin procent majoritar Partidul Social Democrat, candidatul Durac Adam.</em></p>\r\n\r\n<p><em class=\"bold nobold\">In mod similar a fost ales si Consiliul Local al Comunei Corcova, pentru a lua impreuna deciziile administrative in comuna Corcova pe o perioada de 4 ani (pana la alegerile ce vor avea loc in anul 2020).</em></p>\r\n\r\n<a class=\"readon\" href=\"http://www.comunacorcova.ro/organigrama\"><span>Mai multe informatii...</span></a>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title3\";s:15:\"block-variation\";s:7:\"noblock\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:14:\"nomarginbottom\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:13:\"rt-largetitle\";}i:10007;a:14:{s:5:\"title\";s:14:\"Legaturi Utile\";s:4:\"text\";s:841:\"<ul class=\"menu\">\r\n<li class=\"item-180\"><a target=\"_blank\" href=\"http://www.primariadrobeta.ro\">Primaria Drobeta</a>\r\n</li><li class=\"item-181\"><a target=\"_blank\" href=\"http://isj.mh.edu.ro/\">Inspectoratul Scolar</a>\r\n</li><li class=\"item-182\"><a target=\"_blank\" href=\"http://mh.politiaromana.ro\">Politia Mehedinti</a>\r\n</li><li class=\"item-183\"><a target=\"_blank\" href=\"http://www.pna.ro\">Directia Nationala Anticoruptie</a>\r\n</li><li class=\"item-184\"><a target=\"_blank\" href=\"http://www.anpc.gov.ro\">Protectia Consumatorului</a>\r\n</li><li class=\"item-186\"><a target=\"_blank\" href=\"http://www.ambulantamh.ro\">Ambulanta Mehedinti</a>\r\n</li><li class=\"item-187\"><a target=\"_blank\" href=\"http://www.guv.ro\">Guvernul Romaniei</a>\r\n</li><li class=\"item-188\"><a target=\"_blank\" href=\"http://www.presidency.ro\">Presedintia Romaniei</a>\r\n</li></ul>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title2\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:0:\"\";}i:10008;a:14:{s:5:\"title\";s:11:\"Organigrama\";s:4:\"text\";s:607:\"<span class=\"icon-legal fp-icon\"></span>\r\n\r\n<h4 class=\"nomargintop largepaddingtop\"><a href=\"http://www.comunacorcova.ro/organigrama\"><em>Lista Consiliului Local care administreaza comuna Corcova din judetul Mehedinti.</em></a></h4>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<p>Conform alegerilor locale din <strong>2016</strong> oferim lista tuturor celor care au fost alesi pentru a reprezenta aceasta comuna din punct de vedere administrativ, politic si social.</p>\r\n\r\n<p class=\"rt-center nomarginbottom\"><a class=\"readon\" href=\"http://www.comunacorcova.ro/organigrama\"><span>Mai multe informatii...</span></a></p>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title1\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:0:\"\";}i:10009;a:14:{s:5:\"title\";s:7:\"Istoria\";s:4:\"text\";s:533:\"<span class=\"icon-flag fp-icon\"></span>\r\n\r\n<h4 class=\"nomargintop largepaddingtop\"><a href=\"http://www.comunacorcova.ro/istoria\"><em>Corcova este atestat în hrisovul emis de Radu cel Frumos, anul 1472.</em></a></h4>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<p> Într-un hrisov datat din 29 iunie 1497, Radu cel Mare face danie Mânăstirii Tismana 300 vedre de vin provenit de la Jidoștița.</p>\r\n\r\n<p class=\"rt-center nomarginbottom\"><a class=\"readon\" href=\"http://www.comunacorcova.ro/istoria\"><span>Mai multe informatii...</span></a></p>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title1\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:0:\"\";}i:10010;a:14:{s:5:\"title\";s:9:\"Geografia\";s:4:\"text\";s:598:\"<div class=\"rt-image rt-floatleft smallmargintop largemarginbottom\">\r\n  <img class=\"rt-image\" src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/center/1.jpg\" width=\"99\" height=\"92\" alt=\"image\" />\r\n</div>\r\n\r\n<p class=\"smallmargintop\"><strong>Comuna Corcova este situată în nord-estul judeţului Mehedinţi</strong>, sud-vestul României, la o distanță de 55 km de municipiul reședință de județ, orașul Drobeta Turnu Severin.</p>\r\n\r\n<p class=\"rt-center nomarginbottom\"><a class=\"readon\" href=\"http://www.comunacorcova.ro/geografia\"><span>Mai multe informatii...</span></a></p>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:0:\"\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:6:\"center\";}i:10011;a:14:{s:5:\"title\";s:19:\"Educatia si Cultura\";s:4:\"text\";s:596:\"<span class=\"icon-book fp-icon\"></span>\r\n\r\n<h4 class=\"nomargintop largepaddingtop\"><a href=\"http://www.comunacorcova.ro/educatia\"><em>În comuna Corcova funcţionează unităţi de învăţământ, preșcolar și şcolar.</em></a></h4>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<p>La nivel local există <strong>2 cămine culturale</strong>. În cadrul acestora se organizează dansuri susținute de către ansambluri folclorice, evenimente culturale, etc.</p>\r\n\r\n<p class=\"rt-center nomarginbottom\"><a class=\"readon\" href=\"http://www.comunacorcova.ro/educatia\"><span>Mai multe informatii...</span></a></p>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title1\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:0:\"\";}i:10012;a:14:{s:5:\"title\";s:23:\"Cu sprijinul Guvernului\";s:4:\"text\";s:245:\"<a href=\"http://www.guv.ro\" target=\"_blank\">\r\n  <span class=\"rt-image rt-floatleft smallmargintop\">\r\n    <img alt=\"Guvernul Romaniei\" src=\"http://www.comunacorcova.ro/dosare/imagini/design/frontpage/stema/stema_romaniei.png\"/>\r\n  </span>\r\n</a>\r\n\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title1\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:0:\"\";}i:10013;a:14:{s:5:\"title\";s:0:\"\";s:4:\"text\";s:780:\"<ul class=\"menu\">\r\n<li class=\"item-189\"><a target=\"_blank\" href=\"http://www.comunacorcova.ro/dosare/documente/2016/buget_2016.06.08.pdf\">Buget: 2016.06.08</a>\r\n\r\n</li><li class=\"item-190\"><a target=\"_blank\" href=\"http://www.comunacorcova.ro/dosare/documente/2016/finante_2016.04.25.pdf\">Finante: 2016.04.25</a>\r\n\r\n</li><li class=\"item-191\"><a target=\"_blank\" href=\"http://www.comunacorcova.ro/dosare/documente/2016/investitii_2016.02.05.pdf\">Investitii: 2016.02.05</a>\r\n\r\n</li><li class=\"item-192\"><a target=\"_blank\" href=\"http://www.comunacorcova.ro/dosare/documente/2015/buget_2015.12.17.pdf\">Buget: 2015.12.17</a>\r\n\r\n</li><li class=\"item-193\"><a target=\"_blank\" href=\"http://www.comunacorcova.ro/dosare/documente/2015/finante_2015.11.06.pdf\">Finante: 2015.11.06</a>\r\n</li></ul>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:0:\"\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:21:\"horizmenu bottom-menu\";}i:10015;a:14:{s:5:\"title\";s:9:\"Copyright\";s:4:\"text\";s:407:\"<p><strong>NOTA:</strong> Tot continutul acestui site este <strong>public</strong> si poate fi copiat pe orice aparat conectat la interent. Imaginile sunt extrase din strategia de dezvoltare sau de pe internet.</p>\r\n\r\n<p><strong>Distribuirea</strong> si/sau <strong>modificarea</strong> continutului acestui site sunt strict interzise. Informatiile apartin Consilului Local Corcova si Primariei Corcova.</p>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title3\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:30:\"largemargintop largepaddingtop\";}i:10016;a:14:{s:5:\"title\";s:18:\"Detalii de Contact\";s:4:\"text\";s:894:\"<img class=\"rt-floatleft\" alt=\"image\" src=\"http://www.comunacorcova.ro/wp-content/rockettheme/rt_ximenia_wp/frontpage/general/fp-footer-icon1.png\" />\r\n<a href=\"#\"><em class=\"bold\"> (+4) 0252 38 34 64</em></a>\r\n\r\n<div class=\"clear largemarginbottom\">&nbsp;</div>\r\n\r\n<img class=\"rt-floatleft\" alt=\"image\" src=\"http://www.comunacorcova.ro/wp-content/rockettheme/rt_ximenia_wp/frontpage/general/fp-footer-icon2.png\" />\r\n<em class=\"bold\">\r\n  <strong>Primaria Corcova</strong><br />\r\n</em>\r\n<em class=\"bold nobold\">\r\n  Comuna Corcova<br />\r\n  Judetul Mehedinti<br />\r\n  Romania\r\n</em>\r\n\r\n<div class=\"clear largemarginbottom\">&nbsp;</div>\r\n\r\n<img class=\"rt-floatleft\" alt=\"image\" src=\"http://www.comunacorcova.ro/wp-content/rockettheme/rt_ximenia_wp/frontpage/general/fp-footer-icon3.png\" />\r\n<em class=\"bold\">\r\n<span>contact</span>\r\n<span>@</span>\r\n<span>comunacorcova</span>\r\n<span>.ro</span>\r\n</em>\";s:6:\"filter\";b:0;s:12:\"widget-style\";s:0:\"\";s:13:\"box-variation\";s:0:\"\";s:15:\"title-variation\";s:6:\"title3\";s:15:\"block-variation\";s:0:\"\";s:16:\"shadow-variation\";s:0:\"\";s:16:\"corner-variation\";s:0:\"\";s:15:\"align-variation\";s:0:\"\";s:16:\"margin-variation\";s:0:\"\";s:17:\"padding-variation\";s:0:\"\";s:11:\"title-style\";s:0:\"\";s:17:\"custom-variations\";s:30:\"largemargintop largepaddingtop\";}s:12:\"_multiwidget\";i:1;}s:25:\"widget_rokgallery_options\";a:2:{i:10003;a:47:{s:5:\"title\";s:27:\"Crampeie din Comuna Corcova\";s:10:\"gallery_id\";s:1:\"1\";s:4:\"link\";s:11:\"rokbox_full\";s:16:\"default_menuitem\";s:28:\"http://www.comunacorcova.ro/\";s:10:\"show_title\";s:1:\"0\";s:7:\"caption\";s:1:\"0\";s:7:\"sort_by\";s:6:\"random\";s:14:\"sort_direction\";s:3:\"ASC\";s:11:\"limit_count\";s:1:\"4\";s:5:\"style\";s:5:\"light\";s:6:\"layout\";s:4:\"grid\";s:7:\"columns\";s:1:\"4\";s:6:\"arrows\";s:7:\"onh